import { Hono } from 'hono';
import { z } from 'zod';
import { validate } from '../utils/validation.js';
import { success, error } from '../utils/response.js';
import { triggerPushNotification } from '../utils/push.js';

const communication = new Hono();

// Teacher token encryption constants (matched with teacher-portal/login.html & index.html)
const TEACHER_SALT = 'sunnybridge2024';
const TEACHER_KEY = 'sb_teacher_key_v1';

/**
 * Decode teacher token generated by teacher portal
 * Format: XOR(sunnybridge2024:<teacherId>, 'sb_teacher_key_v1') -> base64
 */
export function decodeTeacherToken(token) {
  if (!token || typeof token !== 'string') return null;
  try {
    const decoded = atob(token);
    let result = '';
    for (let i = 0; i < decoded.length; i++) {
      result += String.fromCharCode(decoded.charCodeAt(i) ^ TEACHER_KEY.charCodeAt(i % TEACHER_KEY.length));
    }
    const parts = result.split(':');
    if (parts.length !== 2 || parts[0] !== TEACHER_SALT) return null;
    const teacherId = parseInt(parts[1], 10);
    return isNaN(teacherId) ? null : teacherId;
  } catch {
    return null;
  }
}

/**
 * Helper to encode teacher token (used for testing and parity)
 */
export function encodeTeacherToken(teacherId) {
  const data = TEACHER_SALT + ':' + teacherId;
  let result = '';
  for (let i = 0; i < data.length; i++) {
    result += String.fromCharCode(data.charCodeAt(i) ^ TEACHER_KEY.charCodeAt(i % TEACHER_KEY.length));
  }
  return btoa(result);
}

/**
 * Helper to get student's current teacher derived from most recent class
 * Rule: date DESC, id DESC with teacher_id IS NOT NULL; returns null if none
 */
export async function getCurrentTeacherId(DB, studentId) {
  const row = await DB.prepare(
    'SELECT teacher_id FROM classes WHERE student_id = ? AND teacher_id IS NOT NULL ORDER BY date DESC, id DESC LIMIT 1'
  ).bind(studentId).first();
  return row ? row.teacher_id : null;
}

/**
 * Verify admin credentials
 * Supports Authorization Bearer token and X-API-Key header against env.API_KEY / default key
 */
function verifyAdmin(c) {
  const authHeader = c.req.header('Authorization');
  const apiKeyHeader = c.req.header('X-API-Key');
  let token = authHeader || '';
  if (token.startsWith('Bearer ')) {
    token = token.slice(7);
  }
  if (!token && apiKeyHeader) {
    token = apiKeyHeader;
  }
  // 与 middleware/auth.js 一致：只认 env.API_KEY（未配时为 dev-api-key），不留任何写死在代码里的备用 key
  const validApiKey = c.env.API_KEY || 'dev-api-key';
  return !!token && token === validApiKey;
}

/**
 * Verify parent credentials
 * Validates student_id + access_token against students table
 */
async function verifyParent(DB, studentId, accessToken) {
  if (!studentId || !accessToken) return null;
  return await DB.prepare(
    'SELECT id, name, parent_name, total_hours, used_hours, access_token FROM students WHERE id = ? AND access_token = ? AND access_token IS NOT NULL'
  ).bind(studentId, accessToken).first();
}

/**
 * Notification linkage helper:
 * Writes to notification_history and triggers push notification via triggerPushNotification
 */
async function notifyParentReply(DB, studentId, title, body) {
  try {
    await triggerPushNotification(DB, 'parent', studentId, 'parent_message_reply', title, body, null);
  } catch (err) {
    console.error('Failed to notify parent:', err);
  }
}

// ============================================================================
// 家长端点 (Parent Endpoints)
// ============================================================================

/**
 * GET /api/v1/communication/conversation?student_id=&access_token=
 * 返回该学员会话＋家长可见的消息
 * 可见规则：家长自发消息全部可见；老师/学管回复仅 published 可见；internal 永远不可见
 */
communication.get('/conversation', async (c) => {
  const DB = c.env.DB;
  const studentIdParam = c.req.query('student_id');
  const accessToken = c.req.query('access_token');

  if (!studentIdParam || !accessToken) {
    return c.json(error('UNAUTHORIZED', '缺少 student_id 或 access_token'), 401);
  }

  const studentId = parseInt(studentIdParam, 10);
  if (isNaN(studentId) || studentId <= 0) {
    return c.json(error('BAD_REQUEST', '无效的 student_id'), 400);
  }

  const student = await verifyParent(DB, studentId, accessToken);
  if (!student) {
    return c.json(error('UNAUTHORIZED', '学员身份校验失败或 access_token 无效'), 401);
  }

  const conversation = await DB.prepare(
    'SELECT * FROM parent_conversations WHERE student_id = ?'
  ).bind(student.id).first();

  if (!conversation) {
    return c.json(success({ conversation: null, messages: [] }));
  }

  // 消息可见过滤：排除 internal；仅允许家长本人消息或 published 回复
  const messagesResult = await DB.prepare(
    `SELECT id, conversation_id, sender_role, sender_name, content_zh, content_en,
            routing_type, relay_status, visibility, created_at, published_at
     FROM parent_conversation_messages
     WHERE conversation_id = ?
       AND visibility = 'visible'
       AND (sender_role = 'parent' OR relay_status = 'published')
     ORDER BY created_at ASC, id ASC`
  ).bind(conversation.id).all();

  return c.json(success({
    conversation,
    messages: messagesResult.results || []
  }));
});

const parentMessageSchema = z.object({
  student_id: z.coerce.number().int().positive(),
  access_token: z.string().min(1),
  content_zh: z.string().min(1).max(2000)
});

/**
 * POST /api/v1/communication/message
 * 新建家长消息 (sender_role=parent, relay_status=pending)
 * 限制：content_zh 限 2000 字；同一学员 1 小时内最多 10 条 (429)
 */
communication.post('/message', validate(parentMessageSchema), async (c) => {
  const DB = c.env.DB;
  const data = c.req.validated;
  const { student_id, access_token, content_zh } = data;

  const student = await verifyParent(DB, student_id, access_token);
  if (!student) {
    return c.json(error('UNAUTHORIZED', '学员身份校验失败或 access_token 无效'), 401);
  }

  // 频控检查：同一学员 1 小时内最多 10 条
  const rateLimitCheck = await DB.prepare(
    `SELECT COUNT(*) as count FROM parent_conversation_messages m
     JOIN parent_conversations c ON m.conversation_id = c.id
     WHERE c.student_id = ? AND m.sender_role = 'parent' AND m.created_at >= datetime('now', '-1 hour')`
  ).bind(student.id).first();

  if (rateLimitCheck && rateLimitCheck.count >= 10) {
    return c.json(error('RATE_LIMITED', '发送过于频繁，同一学员 1 小时内最多发送 10 条留言'), 429);
  }

  // 获取或初始化会话
  let conversation = await DB.prepare(
    'SELECT * FROM parent_conversations WHERE student_id = ?'
  ).bind(student.id).first();

  if (!conversation) {
    const derivedTeacherId = await getCurrentTeacherId(DB, student.id);
    const insertConv = await DB.prepare(
      "INSERT INTO parent_conversations (student_id, teacher_id, last_message_at, created_at) VALUES (?, ?, datetime('now'), datetime('now'))"
    ).bind(student.id, derivedTeacherId).run();

    conversation = await DB.prepare('SELECT * FROM parent_conversations WHERE id = ?').bind(insertConv.meta.last_row_id).first();
  } else {
    await DB.prepare("UPDATE parent_conversations SET last_message_at = datetime('now') WHERE id = ?").bind(conversation.id).run();
  }

  const senderName = student.parent_name || student.name || '家长';

  // 插入家长留言
  const insertMsg = await DB.prepare(
    `INSERT INTO parent_conversation_messages
     (conversation_id, sender_role, sender_name, content_zh, relay_status, visibility, created_at)
     VALUES (?, 'parent', ?, ?, 'pending', 'visible', datetime('now'))`
  ).bind(conversation.id, senderName, content_zh).run();

  const newMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(insertMsg.meta.last_row_id).first();

  return c.json(success({
    message: newMsg,
    conversation
  }), 201);
});

// ============================================================================
// 教师端点 (Teacher Endpoints)
// ============================================================================

/**
 * GET /api/v1/communication/teacher/inbox?teacher_id=&token=
 * 只返回分给该老师的会话 (conversation.teacher_id＝本人)，含待回的转发消息 (forwarded_to_teacher) 与已发布历史
 */
communication.get('/teacher/inbox', async (c) => {
  const DB = c.env.DB;
  const teacherIdParam = c.req.query('teacher_id');
  const token = c.req.query('token');

  if (!teacherIdParam || !token) {
    return c.json(error('UNAUTHORIZED', '缺少 teacher_id 或 token'), 401);
  }

  const teacherId = parseInt(teacherIdParam, 10);
  if (isNaN(teacherId) || teacherId <= 0) {
    return c.json(error('BAD_REQUEST', '无效的 teacher_id'), 400);
  }

  const authedTeacherId = decodeTeacherToken(token);
  if (!authedTeacherId || authedTeacherId !== teacherId) {
    return c.json(error('FORBIDDEN', '教师 Token 无效或与 teacher_id 不匹配'), 403);
  }

  const teacher = await DB.prepare('SELECT id, name FROM teachers WHERE id = ?').bind(teacherId).first();
  if (!teacher) {
    return c.json(error('NOT_FOUND', '教师不存在'), 404);
  }

  // 查询分给该老师的所有会话
  const convsResult = await DB.prepare(
    `SELECT c.*, s.name as student_name, s.english_name as student_english_name
     FROM parent_conversations c
     JOIN students s ON c.student_id = s.id
     WHERE c.teacher_id = ?
     ORDER BY c.last_message_at DESC`
  ).bind(teacherId).all();

  const conversations = [];
  for (const conv of (convsResult.results || [])) {
    const messages = await DB.prepare(
      `SELECT id, conversation_id, sender_role, sender_name, content_zh, content_en,
              routing_type, relay_status, visibility, forwarded_at, replied_at, published_at, created_at
       FROM parent_conversation_messages
       WHERE conversation_id = ?
         AND visibility = 'visible'
         AND relay_status IN ('forwarded_to_teacher', 'replied_by_teacher', 'published')
       ORDER BY created_at ASC, id ASC`
    ).bind(conv.id).all();

    conversations.push({
      ...conv,
      messages: messages.results || [],
      pending_reply_count: (messages.results || []).filter(m => m.relay_status === 'forwarded_to_teacher').length
    });
  }

  return c.json(success(conversations));
});

const teacherReplySchema = z.object({
  conversation_id: z.coerce.number().int().positive(),
  token: z.string().min(1),
  content_en: z.string().min(1).max(3000)
});

/**
 * POST /api/v1/communication/teacher/reply
 * 老师英文回复 (sender_role=teacher, relay_status=replied_by_teacher, 记 replied_at)
 * 限制：content_en 限 3000 字；回复不自动发布给家长，等 Roger 手写中文后放行
 */
communication.post('/teacher/reply', validate(teacherReplySchema), async (c) => {
  const DB = c.env.DB;
  const data = c.req.validated;
  const { conversation_id, token, content_en } = data;

  const authedTeacherId = decodeTeacherToken(token);
  if (!authedTeacherId) {
    return c.json(error('UNAUTHORIZED', '无效的教师 Token'), 401);
  }

  const teacher = await DB.prepare('SELECT id, name FROM teachers WHERE id = ?').bind(authedTeacherId).first();
  if (!teacher) {
    return c.json(error('NOT_FOUND', '教师不存在'), 404);
  }

  const conversation = await DB.prepare(
    'SELECT * FROM parent_conversations WHERE id = ?'
  ).bind(conversation_id).first();

  if (!conversation) {
    return c.json(error('NOT_FOUND', '会话不存在'), 404);
  }

  // 严格越权校验：必须是分配给本人的会话
  if (conversation.teacher_id !== authedTeacherId) {
    return c.json(error('FORBIDDEN', '越权访问：该会话未分配给您'), 403);
  }

  // 插入老师回复（状态为 replied_by_teacher，不可见给家长）
  const insertMsg = await DB.prepare(
    `INSERT INTO parent_conversation_messages
     (conversation_id, sender_role, sender_name, content_en, routing_type, relay_status, visibility, replied_at, created_at)
     VALUES (?, 'teacher', ?, ?, 'to_teacher', 'replied_by_teacher', 'visible', datetime('now'), datetime('now'))`
  ).bind(conversation.id, teacher.name || 'Teacher', content_en).run();

  await DB.prepare("UPDATE parent_conversations SET last_message_at = datetime('now') WHERE id = ?").bind(conversation.id).run();

  const newMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(insertMsg.meta.last_row_id).first();

  return c.json(success(newMsg));
});

// ============================================================================
// 管理端点 (Admin Endpoints - Roger 一人用)
// ============================================================================

/**
 * GET /api/v1/communication/admin/queue
 * 待办清单，按最旧优先。两类：家长新留言 (pending)、等放行的老师回复 (replied_by_teacher)。
 * 每条带学生上下文：姓名、当前老师、剩余课时、最近上课日期
 */
communication.get('/admin/queue', async (c) => {
  if (!verifyAdmin(c)) {
    return c.json(error('UNAUTHORIZED', '管理员认证失败，缺少有效凭据'), 401);
  }

  const DB = c.env.DB;

  const messagesResult = await DB.prepare(
    `SELECT m.*,
            c.student_id,
            c.teacher_id as conversation_teacher_id,
            s.name as student_name,
            s.english_name as student_english_name,
            s.total_hours,
            s.used_hours,
            (s.total_hours - s.used_hours) as remaining_hours,
            s.last_class_at
     FROM parent_conversation_messages m
     JOIN parent_conversations c ON m.conversation_id = c.id
     JOIN students s ON c.student_id = s.id
     WHERE m.visibility = 'visible'
       AND m.relay_status IN ('pending', 'replied_by_teacher')
     ORDER BY m.created_at ASC, m.id ASC`
  ).all();

  const items = [];
  for (const item of (messagesResult.results || [])) {
    // 动态推导当前老师（最近课程）
    const derivedTeacherId = await getCurrentTeacherId(DB, item.student_id);
    let derivedTeacherName = null;
    if (derivedTeacherId) {
      const teacherRow = await DB.prepare('SELECT name FROM teachers WHERE id = ?').bind(derivedTeacherId).first();
      derivedTeacherName = teacherRow ? teacherRow.name : null;
    }

    // 最近上课日期：优先从 classes 取实际最近完成或安排的课程日期
    let recentClassDate = item.last_class_at;
    const lastClassRow = await DB.prepare(
      'SELECT date FROM classes WHERE student_id = ? ORDER BY date DESC, id DESC LIMIT 1'
    ).bind(item.student_id).first();
    if (lastClassRow && lastClassRow.date) {
      recentClassDate = lastClassRow.date;
    }

    items.push({
      ...item,
      current_teacher_id: derivedTeacherId,
      current_teacher_name: derivedTeacherName,
      last_class_date: recentClassDate
    });
  }

  return c.json(success(items));
});

const adminForwardSchema = z.object({
  message_id: z.coerce.number().int().positive(),
  teacher_id: z.coerce.number().int().positive().optional(),
  content_en: z.string().min(1)
});

/**
 * POST /api/v1/communication/admin/forward
 * 把家长留言转交外教。content_en 是 Roger 手写的英文版
 * routing_type=to_teacher, relay_status=forwarded_to_teacher, 记 forwarded_at+handled_by
 */
communication.post('/admin/forward', validate(adminForwardSchema), async (c) => {
  if (!verifyAdmin(c)) {
    return c.json(error('UNAUTHORIZED', '管理员认证失败，缺少有效凭据'), 401);
  }

  const DB = c.env.DB;
  const { message_id, teacher_id, content_en } = c.req.validated;

  const message = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(message_id).first();
  if (!message) {
    return c.json(error('NOT_FOUND', '消息不存在'), 404);
  }

  if (message.relay_status !== 'pending') {
    return c.json(error('BAD_REQUEST', '该消息当前不是待处理状态 (pending)'), 400);
  }

  const conversation = await DB.prepare('SELECT * FROM parent_conversations WHERE id = ?').bind(message.conversation_id).first();
  if (!conversation) {
    return c.json(error('NOT_FOUND', '所属会话不存在'), 404);
  }

  // 决定目标老师：请求指定的 teacher_id 或学员最近课程推导
  let targetTeacherId = teacher_id;
  if (!targetTeacherId) {
    targetTeacherId = await getCurrentTeacherId(DB, conversation.student_id);
  }

  if (!targetTeacherId) {
    return c.json(error('BAD_REQUEST', '学员暂无上课教师记录，无法转交外教，请走 direct-reply'), 400);
  }

  const targetTeacher = await DB.prepare('SELECT id, name FROM teachers WHERE id = ?').bind(targetTeacherId).first();
  if (!targetTeacher) {
    return c.json(error('BAD_REQUEST', '指定的教师不存在'), 400);
  }

  // 更新家长留言转交状态
  await DB.prepare(
    `UPDATE parent_conversation_messages
     SET content_en = ?,
         routing_type = 'to_teacher',
         relay_status = 'forwarded_to_teacher',
         forwarded_at = datetime('now'),
         handled_by = 'roger'
     WHERE id = ?`
  ).bind(content_en, message.id).run();

  // 更新会话绑定老师与最后活跃时间
  await DB.prepare(
    "UPDATE parent_conversations SET teacher_id = ?, last_message_at = datetime('now') WHERE id = ?"
  ).bind(targetTeacherId, conversation.id).run();

  const updatedMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(message.id).first();

  return c.json(success({
    message: updatedMsg,
    assigned_teacher_id: targetTeacherId,
    assigned_teacher_name: targetTeacher.name
  }));
});

const adminDirectReplySchema = z.object({
  conversation_id: z.coerce.number().int().positive(),
  content_zh: z.string().min(1)
});

/**
 * POST /api/v1/communication/admin/direct-reply
 * 教务类 Roger 直接中文回复家长 (sender_role=advisor, relay_status 直接 published)
 * 更新 last_message_at 并写 notification_history
 */
communication.post('/admin/direct-reply', validate(adminDirectReplySchema), async (c) => {
  if (!verifyAdmin(c)) {
    return c.json(error('UNAUTHORIZED', '管理员认证失败，缺少有效凭据'), 401);
  }

  const DB = c.env.DB;
  const { conversation_id, content_zh } = c.req.validated;

  const conversation = await DB.prepare('SELECT * FROM parent_conversations WHERE id = ?').bind(conversation_id).first();
  if (!conversation) {
    return c.json(error('NOT_FOUND', '会话不存在'), 404);
  }

  // 插入学管直接回复消息
  const insertRes = await DB.prepare(
    `INSERT INTO parent_conversation_messages
     (conversation_id, sender_role, sender_name, content_zh, routing_type, relay_status, visibility, handled_by, published_at, created_at)
     VALUES (?, 'advisor', '课程顾问', ?, 'direct_advisor', 'published', 'visible', 'roger', datetime('now'), datetime('now'))`
  ).bind(conversation.id, content_zh).run();

  // 若该会话中有 pending 的家长留言，标记为 published，清除待办
  await DB.prepare(
    `UPDATE parent_conversation_messages
     SET relay_status = 'published', routing_type = COALESCE(routing_type, 'direct_advisor'), handled_by = 'roger'
     WHERE conversation_id = ? AND relay_status = 'pending'`
  ).bind(conversation.id).run();

  await DB.prepare("UPDATE parent_conversations SET last_message_at = datetime('now') WHERE id = ?").bind(conversation.id).run();

  // 联动通知家长
  await notifyParentReply(DB, conversation.student_id, '💬 家校沟通新回复', content_zh);

  const replyMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(insertRes.meta.last_row_id).first();

  return c.json(success(replyMsg));
});

const adminPublishSchema = z.object({
  message_id: z.coerce.number().int().positive(),
  content_zh: z.string().min(1)
});

/**
 * POST /api/v1/communication/admin/publish
 * 放行老师回复。content_zh 是 Roger 手写的中文版
 * relay_status=published，记 published_at＋handled_by；更新 last_message_at 并写 notification_history
 */
communication.post('/admin/publish', validate(adminPublishSchema), async (c) => {
  if (!verifyAdmin(c)) {
    return c.json(error('UNAUTHORIZED', '管理员认证失败，缺少有效凭据'), 401);
  }

  const DB = c.env.DB;
  const { message_id, content_zh } = c.req.validated;

  const message = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(message_id).first();
  if (!message) {
    return c.json(error('NOT_FOUND', '消息不存在'), 404);
  }

  const conversation = await DB.prepare('SELECT * FROM parent_conversations WHERE id = ?').bind(message.conversation_id).first();
  if (!conversation) {
    return c.json(error('NOT_FOUND', '所属会话不存在'), 404);
  }

  // 放行老师回复
  await DB.prepare(
    `UPDATE parent_conversation_messages
     SET content_zh = ?,
         relay_status = 'published',
         published_at = datetime('now'),
         handled_by = 'roger'
     WHERE id = ?`
  ).bind(content_zh, message.id).run();

  // 会话中对应的转发消息也标记 published
  await DB.prepare(
    "UPDATE parent_conversation_messages SET relay_status = 'published' WHERE conversation_id = ? AND relay_status = 'forwarded_to_teacher'"
  ).bind(conversation.id).run();

  await DB.prepare("UPDATE parent_conversations SET last_message_at = datetime('now') WHERE id = ?").bind(conversation.id).run();

  // 联动通知家长
  await notifyParentReply(DB, conversation.student_id, '💬 老师回复通知', content_zh);

  const publishedMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(message.id).first();

  return c.json(success(publishedMsg));
});

const internalNoteSchema = z.object({
  conversation_id: z.coerce.number().int().positive(),
  content: z.string().min(1)
});

/**
 * POST /api/v1/communication/admin/internal-note
 * 内部备注 (visibility=internal)，家长端和教师端接口永远不返回它
 */
communication.post('/admin/internal-note', validate(internalNoteSchema), async (c) => {
  if (!verifyAdmin(c)) {
    return c.json(error('UNAUTHORIZED', '管理员认证失败，缺少有效凭据'), 401);
  }

  const DB = c.env.DB;
  const { conversation_id, content } = c.req.validated;

  const conversation = await DB.prepare('SELECT * FROM parent_conversations WHERE id = ?').bind(conversation_id).first();
  if (!conversation) {
    return c.json(error('NOT_FOUND', '会话不存在'), 404);
  }

  const insertRes = await DB.prepare(
    `INSERT INTO parent_conversation_messages
     (conversation_id, sender_role, sender_name, content_zh, visibility, relay_status, handled_by, created_at)
     VALUES (?, 'advisor', 'Roger (内部备注)', ?, 'internal', 'published', 'roger', datetime('now'))`
  ).bind(conversation.id, content).run();

  const noteMsg = await DB.prepare('SELECT * FROM parent_conversation_messages WHERE id = ?').bind(insertRes.meta.last_row_id).first();

  return c.json(success(noteMsg));
});

export default communication;
